/* 1) 改强度 (同 id 会替换, 颜色保持新色) */
ssp.lightTool.createAmbientLight({ id: 'main', color: '#ffffff', intensity: 0.3 });

/* 2) 模拟白天/黑夜切换 (用同一个 id) */
ssp.lightTool.createAmbientLight({ id: 'main', color: '#ffffff', intensity: 1.0 });  // 白天
setTimeout(() => ssp.lightTool.createAmbientLight({ id: 'main', color: '#ffe4b5', intensity: 0.2 }), 3000);  // 夜晚

/* 3) 调暗 / 调亮 */
ssp.lightTool.createAmbientLight({ id: 'main', color: '#fff5e6', intensity: 0.6 });
